=== src/app/globals.css
:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #5f6368;
  --border: #d9d9de;
  --surface: #f6f6f8;
  --accent: #1f5fbf;
  --accent-fg: #ffffff;
  --danger: #b3261e;
  --done: #2e7d32;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #141416;
    --fg: #ececf0;
    --muted: #a0a0aa;
    --border: #34343a;
    --surface: #1d1d21;
    --accent: #7aa7ff;
    --accent-fg: #0b1020;
    --danger: #ff8a80;
    --done: #81c784;
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

main { max-width: 56rem; margin: 0 auto; padding: 1.5rem 1rem 4rem; }
h1 { font-size: 1.6rem; margin: 0 0 1rem; }
h2 { font-size: 1.25rem; }
h3 { font-size: 1.05rem; margin: 0; }
a { color: var(--accent); }
code { background: var(--surface); padding: 0 0.25em; border-radius: 4px; }

.site-header {
  display: flex; flex-wrap: wrap; gap: 0.75rem 1.5rem; align-items: center; justify-content: space-between;
  padding: 0.75rem 1rem; border-bottom: 1px solid var(--border);
}

.row { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: center; }
.stack { display: grid; gap: 0.75rem; }
.narrow { max-width: 24rem; }
.muted { color: var(--muted); }
.grow { flex: 1 1 14rem; }
.full { grid-column: 1 / -1; }

label { display: grid; gap: 0.25rem; font-size: 0.9rem; font-weight: 500; }
input, select, textarea, button { font: inherit; }
input, select, textarea {
  padding: 0.45rem 0.6rem; border: 1px solid var(--border); border-radius: 6px;
  background: var(--bg); color: var(--fg); min-width: 0;
}
textarea { resize: vertical; }

button {
  padding: 0.45rem 0.9rem; border-radius: 6px; border: 1px solid var(--accent);
  background: var(--accent); color: var(--accent-fg); cursor: pointer;
}
button:disabled { opacity: 0.6; cursor: progress; }
button.secondary { background: transparent; color: var(--fg); border-color: var(--border); }
button.danger { background: var(--danger); border-color: var(--danger); color: var(--bg); }
button.link { background: none; border: none; color: var(--accent); padding: 0; text-decoration: underline; }

.error { color: var(--danger); margin: 0; }
ul.error { padding-left: 1.2rem; }
.banner { padding: 0.75rem 1rem; border: 1px solid var(--danger); border-radius: 8px; }

.card { border: 1px solid var(--border); border-radius: 8px; padding: 1rem; margin-bottom: 1.25rem; }
details.card > summary { cursor: pointer; font-weight: 600; }
details.card[open] > summary { margin-bottom: 0.75rem; }

.task-form { display: grid; grid-template-columns: 2fr repeat(3, minmax(7rem, 1fr)); gap: 0.75rem; align-items: end; }
@media (max-width: 40rem) { .task-form { grid-template-columns: 1fr 1fr; } .task-form .grow { grid-column: 1 / -1; } }

.filters { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: end; margin-bottom: 0.5rem; }

.tasks { list-style: none; padding: 0; margin: 0; display: grid; gap: 0.5rem; }
.task {
  display: flex; gap: 0.75rem; align-items: flex-start; padding: 0.75rem;
  border: 1px solid var(--border); border-radius: 8px;
}
.task.editing { display: block; }
.task > input[type="checkbox"] { margin-top: 0.3rem; width: 1.1rem; height: 1.1rem; }
.task-body { flex: 1; min-width: 0; }
.task-title { font-weight: 600; overflow-wrap: anywhere; }
.task.done .task-title { text-decoration: line-through; color: var(--muted); }
.task-notes { white-space: pre-wrap; color: var(--muted); overflow-wrap: anywhere; }
.task-meta { display: flex; flex-wrap: wrap; gap: 0.75rem; font-size: 0.85rem; color: var(--muted); }
.task-actions { display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center; justify-content: flex-end; }
.badge { border: 1px solid var(--border); border-radius: 999px; padding: 0 0.5rem; }
.status-done { color: var(--done); border-color: var(--done); }

.empty { text-align: center; padding: 2rem 1rem; border: 1px dashed var(--border); border-radius: 8px; }

.summary { display: flex; flex-wrap: wrap; gap: 1.5rem; list-style: none; padding: 0; }
table { width: 100%; border-collapse: collapse; margin-top: 0.75rem; font-size: 0.9rem; }
th, td { text-align: left; vertical-align: top; padding: 0.5rem; border-bottom: 1px solid var(--border); }
td { overflow-wrap: anywhere; }
.reasons { margin: 0; padding-left: 1rem; }
