import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";
import { isTaskStatus, type TaskStatus } from "./validation";

export const LIST_LIMIT = 500;

export type Task = Pick<
  Database["public"]["Tables"]["tasks"]["Row"],
  "id" | "title" | "notes" | "due_date" | "priority" | "status"
>;

export type TaskFilters = { q: string; status: TaskStatus | null; priority: number | null };

type SearchParams = Record<string, string | string[] | undefined>;

const first = (value: string | string[] | undefined) => (Array.isArray(value) ? value[0] : value) ?? "";

/** Reads filters from URL search params, ignoring anything invalid. */
export function parseFilters(params: SearchParams): TaskFilters {
  const q = first(params.q).trim().slice(0, 200);
  const status = first(params.status);
  const priority = first(params.priority);
  return {
    q,
    status: isTaskStatus(status) ? status : null,
    priority: /^[1-5]$/.test(priority) ? Number(priority) : null,
  };
}

export const hasActiveFilters = (f: TaskFilters) => Boolean(f.q || f.status || f.priority);

/**
 * Builds a PostgREST `or` filter for a case-insensitive substring match on title and notes.
 * Uses `imatch` (Postgres `~*`) rather than `ilike`, because PostgREST turns every `*` in an
 * `ilike` value into `%` and offers no way to escape it. Regex metacharacters in the search text
 * are escaped so they match literally, and the value is double-quoted so commas and parentheses
 * can't break out of the filter syntax.
 */
export function searchFilter(q: string): string {
  const regexEscaped = q.replace(/[\\^$.*+?()[\]{}|]/g, (c) => `\\${c}`);
  const quoted = `"${regexEscaped.replace(/[\\"]/g, (c) => `\\${c}`)}"`;
  return `title.imatch.${quoted},notes.imatch.${quoted}`;
}

type Client = SupabaseClient<Database>;

/**
 * Live (not deleted) tasks for the signed-in user, up to LIST_LIMIT; RLS scopes rows to that user.
 * `truncated` is true only when more matching tasks exist.
 */
export async function listTasks(
  supabase: Client,
  filters: TaskFilters,
): Promise<{ tasks: Task[]; truncated: boolean }> {
  let query = supabase
    .from("tasks")
    .select("id, title, notes, due_date, priority, status")
    .is("deleted_at", null);

  if (filters.status) query = query.eq("status", filters.status);
  if (filters.priority) query = query.eq("priority", filters.priority);
  if (filters.q) query = query.or(searchFilter(filters.q));

  const { data, error } = await query
    .order("due_date", { ascending: true })
    .order("priority", { ascending: true })
    .order("created_at", { ascending: true })
    // One extra row tells "exactly LIST_LIMIT" apart from "more than LIST_LIMIT".
    .limit(LIST_LIMIT + 1);

  if (error) throw new Error(`Could not load tasks: ${error.message}`);
  return { tasks: data.slice(0, LIST_LIMIT), truncated: data.length > LIST_LIMIT };
}

export async function countLiveTasks(supabase: Client): Promise<number> {
  const { count, error } = await supabase
    .from("tasks")
    .select("id", { count: "exact", head: true })
    .is("deleted_at", null);
  if (error) throw new Error(`Could not count tasks: ${error.message}`);
  return count ?? 0;
}
// Single source of truth for task field rules, shared by the task form and CSV import (R6).

export const TITLE_MAX_LENGTH = 200;
export const NOTES_MAX_LENGTH = 2000;
export const TASK_STATUSES = ["todo", "in_progress", "done"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];

export const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "To do",
  in_progress: "In progress",
  done: "Done",
};

export type TaskInput = {
  title: string;
  due_date: string;
  priority: number;
  notes: string | null;
};

export type RawTaskInput = {
  title?: unknown;
  due_date?: unknown;
  priority?: unknown;
  notes?: unknown;
};

export type ValidationResult =
  | { ok: true; value: TaskInput }
  | { ok: false; errors: string[] };

export const MESSAGES = {
  titleRequired: "title is required",
  titleTooLong: `title must be ${TITLE_MAX_LENGTH} characters or fewer`,
  dueDateRequired: "due_date is required",
  dueDateInvalid: "due_date must be a real date in YYYY-MM-DD format",
  priorityRequired: "priority is required",
  priorityInvalid: "priority must be a whole number from 1 to 5",
  notesTooLong: `notes must be ${NOTES_MAX_LENGTH} characters or fewer`,
} as const;

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const PRIORITY_PATTERN = /^[1-5]$/;

function asTrimmedString(value: unknown): string {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

/** True when `value` is YYYY-MM-DD and names a day that exists on the calendar. */
export function isValidIsoDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);
  if (!match) return false;
  const [year, month, day] = match.slice(1).map(Number);
  // Year 0 doesn't exist in Postgres's (proleptic Gregorian, AD) date type.
  if (year < 1) return false;
  const date = new Date(0);
  // setUTCFullYear avoids Date.UTC's 0–99 → 1900–1999 mapping.
  date.setUTCFullYear(year, month - 1, day);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** Validates every field and returns all failure reasons, not just the first. */
export function validateTaskInput(raw: RawTaskInput): ValidationResult {
  const errors: string[] = [];

  const title = asTrimmedString(raw.title);
  if (title === "") errors.push(MESSAGES.titleRequired);
  else if ([...title].length > TITLE_MAX_LENGTH) errors.push(MESSAGES.titleTooLong);

  const dueDate = asTrimmedString(raw.due_date);
  if (dueDate === "") errors.push(MESSAGES.dueDateRequired);
  else if (!isValidIsoDate(dueDate)) errors.push(MESSAGES.dueDateInvalid);

  const priorityText = asTrimmedString(raw.priority);
  if (priorityText === "") errors.push(MESSAGES.priorityRequired);
  else if (!PRIORITY_PATTERN.test(priorityText)) errors.push(MESSAGES.priorityInvalid);

  const notes = asTrimmedString(raw.notes);
  if ([...notes].length > NOTES_MAX_LENGTH) errors.push(MESSAGES.notesTooLong);

  if (errors.length > 0) return { ok: false, errors };

  return {
    ok: true,
    value: {
      title,
      due_date: dueDate,
      priority: Number(priorityText),
      notes: notes === "" ? null : notes,
    },
  };
}

export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === "string" && (TASK_STATUSES as readonly string[]).includes(value);
}
import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { supabaseEnv } from "@/lib/supabase/env";

const PUBLIC_PATHS = ["/login"];

/**
 * Refreshes the Supabase session cookie and makes an optimistic redirect.
 * This is not the authorisation check: requireUser() and RLS are.
 */
export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request });
  const { url, publishableKey } = supabaseEnv();

  const supabase = createServerClient(url, publishableKey, {
    cookies: {
      getAll() {
        return request.cookies.getAll();
      },
      setAll(cookiesToSet, headers) {
        for (const { name, value } of cookiesToSet) request.cookies.set(name, value);
        response = NextResponse.next({ request });
        for (const { name, value, options } of cookiesToSet) response.cookies.set(name, value, options);
        for (const [key, value] of Object.entries(headers ?? {})) response.headers.set(key, value);
      },
    },
  });

  // getClaims validates the JWT and refreshes an expired session (writing new cookies above).
  const { data } = await supabase.auth.getClaims();
  const signedIn = Boolean(data?.claims);
  const { pathname } = request.nextUrl;
  const isPublic = PUBLIC_PATHS.some((p) => pathname === p || pathname.startsWith(`${p}/`));

  if (!signedIn && !isPublic) return redirectKeepingCookies(request, response, "/login");

  if (signedIn && isPublic) {
    // getClaims only checks the JWT locally, so a revoked session still looks signed in until
    // the token expires. requireUser() asks the auth server and would send /tasks straight back
    // here, looping. Confirm with the auth server before leaving /login (only /login pays this),
    // and clear the stale session if it fails.
    const { data: userData, error } = await supabase.auth.getUser();
    if (!error && userData.user) return redirectKeepingCookies(request, response, "/tasks");
    await supabase.auth.signOut({ scope: "local" });
  }
  return response;
}

function redirectKeepingCookies(request: NextRequest, from: NextResponse, pathname: string) {
  const target = request.nextUrl.clone();
  target.pathname = pathname;
  target.search = "";
  const redirect = NextResponse.redirect(target);
  for (const cookie of from.cookies.getAll()) redirect.cookies.set(cookie);
  return redirect;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)"],
};
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
  experimental: {
    serverActions: {
      // CSV import accepts files up to 1 MB; leave headroom for multipart overhead.
      // The 1 MB / 5,000-row app limit is enforced inside the action.
      bodySizeLimit: "2mb",
    },
  },
};

export default nextConfig;
