export async function countLiveTasks(supabase: Client): Promise<number> {
  const { count, error } = await supabase
    .from("tasks")
    .select("id", { count: "exact", head: true })
    .is("deleted_at", null);
  if (error) throw new Error(`Could not count tasks: ${error.message}`);
