3:A small task-list web app where each signed-in user manages their own tasks and can bulk-import them from a CSV file. It's built with TypeScript, Next.js 16 (App Router), Node.js and PostgreSQL (local Supabase), and per-user isolation is enforced by Postgres row-level security.
5:> - Requirements: [`docs/brainstorms/2026-10-08-task-list-csv-import-requirements.md`](docs/brainstorms/2026-10-08-task-list-csv-import-requirements.md)
13:- Every user sees **only their own tasks**. This is enforced in the database with row-level security, not only in application code, so a bug in the UI or API can't leak another user's data.
16:- Each task has a **title** (required, up to 200 characters), **notes** (up to 2,000 characters), **due date**, **priority** (1–5) and **status** (to do, in progress, done).
22:- Filter by status and priority. Filters live in the URL, so a filtered view can be bookmarked.
26:- Upload a CSV with the columns `title, due_date, priority, notes`. Header names are matched case-insensitively and in any order. Extra columns are ignored.
30:  - the priority is missing or not a whole number from 1 to 5 (e.g. `high`, `2.5`, `0`)
49:### Prerequisites
68:| `npm run db:reset` | Rebuild the local database from `supabase/migrations/` |
71:| `npm run build` / `npm start` | Production build and server |
84:| `tests/unit/validation.test.ts` | Title, `YYYY-MM-DD` date (format and real-calendar checks, leap years) and priority rules; all reasons reported together |
104:  | 6 | priority `high` | rejected: priority must be a whole number from 1 to 5 |
114:## Design decisions
116:- **Isolation is enforced by Postgres.** The app only talks to Supabase as the signed-in user (publishable key plus session cookies). RLS policies check `user_id = auth.uid()`. Column-level grants stop clients writing `user_id`, `id` or timestamps, and there is no `DELETE` grant, so tasks can only be soft-deleted. The secret key is used only by the test helper that creates test users.
120:- **Next.js 16:** `src/proxy.ts` (formerly middleware) refreshes the session and redirects signed-out users, but it is only an optimistic check. Before sending a signed-in user away from `/login` it confirms the session with the auth server, so a revoked session can't loop between `/login` and `/tasks`. `requireUser()` runs in every Server Action and data read. Cache Components stays on: session reads sit behind `<Suspense>`, and no task data is cached.
121:- **The rejects file is built in the browser** from the import result, so nothing is stored on the server.
145:This project is built with AI assistance (Claude Code). Planning artefacts are in `docs/`. Session transcripts are not included yet: they will be added to `ai-log/` after a privacy check.
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { listTasks, parseFilters } from "@/lib/tasks/queries";
import { assertSupabaseRunning, createTestUser, deleteTestUsers, type TestUser } from "./helpers";

describe("listTasks", () => {
  let user: TestUser;

  beforeAll(async () => {
    await assertSupabaseRunning();
    user = await createTestUser("queries");
    const { error } = await user.client.from("tasks").insert([
      { title: "Buy milk, eggs", due_date: "2026-01-06", priority: 2, notes: "corner shop" },
      { title: "Discount 50% off", due_date: "2026-01-05", priority: 4, status: "done" },
      { title: "Read (chapter 3)", due_date: "2026-01-05", priority: 1, notes: 'quote "x" \\ slash' },
      { title: "snake_case rename", due_date: "2026-01-07", priority: 3 },
      { title: "Glob *.csv [a-z]+ files?", due_date: "2026-01-08", priority: 3, notes: "^start | end$" },
      { title: "Deleted task", due_date: "2026-01-05", priority: 1 },
    ], { defaultToNull: false });
    if (error) throw error;
    await user.client.from("tasks").update({ deleted_at: new Date().toISOString() }).eq("title", "Deleted task");
  });

  afterAll(deleteTestUsers);

  const titles = async (params: Record<string, string>) =>
    (await listTasks(user.client, parseFilters(params))).tasks.map((t) => t.title);

  it("lists live tasks ordered by due date then priority", async () => {
    expect(await titles({})).toEqual([
      "Read (chapter 3)",
      "Discount 50% off",
      "Buy milk, eggs",
      "snake_case rename",
      "Glob *.csv [a-z]+ files?",
    ]);
  });

  it("searches title and notes case-insensitively", async () => {
    expect(await titles({ q: "CORNER" })).toEqual(["Buy milk, eggs"]);
    expect(await titles({ q: "milk" })).toEqual(["Buy milk, eggs"]);
  });

  it.each([
    ["milk, eggs", ["Buy milk, eggs"]],
    ["(chapter", ["Read (chapter 3)"]],
    ["50%", ["Discount 50% off"]],
    ["%", ["Discount 50% off"]],
    ["_", ["snake_case rename"]],
    ['"x"', ["Read (chapter 3)"]],
    ["\\", ["Read (chapter 3)"]],
    ["*", ["Glob *.csv [a-z]+ files?"]],
    ["*.csv", ["Glob *.csv [a-z]+ files?"]],
    ["u*m", []],
    [".", ["Glob *.csv [a-z]+ files?"]],
    ["[a-z]+", ["Glob *.csv [a-z]+ files?"]],
    ["files?", ["Glob *.csv [a-z]+ files?"]],
    ["^start | end$", ["Glob *.csv [a-z]+ files?"]],
  ])("treats special characters in %j literally", async (q, expected) => {
    expect(await titles({ q })).toEqual(expected);
  });
import { randomUUID } from "node:crypto";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/lib/supabase/database.types";

const NOT_RUNNING =
  "Integration tests need local Supabase. Run `npx supabase start`, then copy the keys from " +
  "`npx supabase status -o env` into .env.local (see .env.example).";

function env() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const publishableKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  const secretKey = process.env.SUPABASE_SECRET_KEY;
  if (!url || !publishableKey || !secretKey) throw new Error(`Missing Supabase env vars. ${NOT_RUNNING}`);
  return { url, publishableKey, secretKey };
}

const noSession = { auth: { persistSession: false, autoRefreshToken: false } };

/** Fails loudly (instead of skipping) when the local stack isn't reachable. */
export async function assertSupabaseRunning() {
  const { url, publishableKey } = env();
  try {
    const res = await fetch(`${url}/auth/v1/health`, { headers: { apikey: publishableKey } });
    if (!res.ok) throw new Error(`status ${res.status}`);
  } catch (error) {
    throw new Error(`Supabase isn't reachable at ${url} (${String(error)}). ${NOT_RUNNING}`);
  }
}

export function anonClient(): SupabaseClient<Database> {
  const { url, publishableKey } = env();
  return createClient<Database>(url, publishableKey, noSession);
}

// Test-only: the secret key never appears in app code.
function adminClient() {
  const { url, secretKey } = env();
  return createClient<Database>(url, secretKey, noSession);
}

