:root {
  --bg: #f7f7fb;
  --surface: #ffffff;
  --surface-2: #f1f2f6;
  --fg: #16171d;
  --muted: #5e6170;
  --border: #e2e3ea;
  --border-strong: #c9cbd6;
  --accent: #3b5bdb;
  --accent-hover: #2f4ac0;
  --accent-soft: #e8edff;
  --accent-fg: #ffffff;
  --danger: #c92a2a;
  --danger-soft: #fdecec;
  --warn: #b35c00;
  --warn-soft: #fff3e0;
  --done: #2b8a3e;
  --done-soft: #e6f6ea;
  --progress: #1971c2;
  --progress-soft: #e7f1fc;
  --ring: 0 0 0 3px color-mix(in srgb, var(--accent) 35%, transparent);
  --shadow-sm: 0 1px 2px rgb(16 18 27 / 6%);
  --shadow: 0 1px 3px rgb(16 18 27 / 8%), 0 4px 12px rgb(16 18 27 / 5%);
  --shadow-lg: 0 10px 30px rgb(16 18 27 / 14%), 0 2px 6px rgb(16 18 27 / 6%);
  --radius: 10px;
  --radius-sm: 7px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1014;
    --surface: #17181e;
    --surface-2: #1f2028;
    --fg: #ececf1;
    --muted: #9c9fae;
    --border: #2b2d37;
    --border-strong: #3c3f4c;
    --accent: #7c95ff;
    --accent-hover: #98abff;
