    --accent-fg: #0b1020;
    --danger: #ff8787;
    --danger-soft: #3a1c1f;
    --warn: #ffb35c;
    --warn-soft: #3a2a14;
    --done: #69db7c;
    --done-soft: #16301d;
    --progress: #74c0fc;
    --progress-soft: #142a3d;
    --shadow-sm: 0 1px 2px rgb(0 0 0 / 40%);
    --shadow: 0 1px 3px rgb(0 0 0 / 40%), 0 4px 12px rgb(0 0 0 / 25%);
    --shadow-lg: 0 10px 30px rgb(0 0 0 / 55%), 0 2px 6px rgb(0 0 0 / 30%);
  }
