:root {
  --bg: #f7f7fb;
  --surface: #ffffff;
  --surface-2: #f1f2f6;
  --fg: #16171d;
  --muted: #5e6170;
  --border: #e2e3ea;
  --border-strong: #c9cbd6;
  --accent: #3b5bdb;
  --accent-hover: #2f4ac0;
  --accent-soft: #e8edff;
  --accent-fg: #ffffff;
  --danger: #c92a2a;
  --danger-soft: #fdecec;
  --warn: #b35c00;
  --warn-soft: #fff3e0;
  --done: #2b8a3e;
  --done-soft: #e6f6ea;
  --progress: #1971c2;
  --progress-soft: #e7f1fc;
  --ring: 0 0 0 3px color-mix(in srgb, var(--accent) 35%, transparent);
  --shadow-sm: 0 1px 2px rgb(16 18 27 / 6%);
  --shadow: 0 1px 3px rgb(16 18 27 / 8%), 0 4px 12px rgb(16 18 27 / 5%);
  --shadow-lg: 0 10px 30px rgb(16 18 27 / 14%), 0 2px 6px rgb(16 18 27 / 6%);
  --radius: 10px;
  --radius-sm: 7px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1014;
    --surface: #17181e;
    --surface-2: #1f2028;
    --fg: #ececf1;
    --muted: #9c9fae;
    --border: #2b2d37;
    --border-strong: #3c3f4c;
    --accent: #7c95ff;
    --accent-hover: #98abff;
    --accent-soft: #1f2645;
    --accent-fg: #0b1020;
    --danger: #ff8787;
    --danger-soft: #3a1c1f;
    --warn: #ffb35c;
    --warn-soft: #3a2a14;
    --done: #69db7c;
    --done-soft: #16301d;
    --progress: #74c0fc;
    --progress-soft: #142a3d;
    --shadow-sm: 0 1px 2px rgb(0 0 0 / 40%);
    --shadow: 0 1px 3px rgb(0 0 0 / 40%), 0 4px 12px rgb(0 0 0 / 25%);
    --shadow-lg: 0 10px 30px rgb(0 0 0 / 55%), 0 2px 6px rgb(0 0 0 / 30%);
  }
}

/* ---------- Base ---------- */

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--fg);
  font: 15px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  -webkit-font-smoothing: antialiased;
}

main { max-width: 56rem; margin: 0 auto; padding: 2rem 1rem 5rem; }
h1 { font-size: 1.65rem; line-height: 1.2; letter-spacing: -0.02em; margin: 0 0 0.35rem; }
h2 { font-size: 1.2rem; letter-spacing: -0.01em; }
h3 { font-size: 1.02rem; margin: 0; }
a { color: var(--accent); text-underline-offset: 2px; }
a:hover { color: var(--accent-hover); }
code { background: var(--surface-2); border: 1px solid var(--border); padding: 0 0.3em; border-radius: 5px; font-size: 0.88em; }
svg { flex-shrink: 0; }

:focus-visible { outline: none; box-shadow: var(--ring); }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 1rem; top: -3rem; z-index: 100;
  background: var(--accent); color: var(--accent-fg); padding: 0.5rem 0.9rem; border-radius: var(--radius-sm);
  text-decoration: none; font-weight: 600;
}
.skip-link:focus { top: 0.75rem; color: var(--accent-fg); }

/* ---------- Utilities ---------- */

.row { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: center; }
.stack { display: grid; gap: 0.9rem; }
.muted { color: var(--muted); }
.small { font-size: 0.82rem; }
.grow { flex: 1 1 14rem; }
.full { grid-column: 1 / -1; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }

/* ---------- Header and navigation ---------- */

.site-header {
  position: sticky; top: 0; z-index: 20;
  background: color-mix(in srgb, var(--surface) 82%, transparent);
  backdrop-filter: saturate(180%) blur(12px);
  -webkit-backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--border);
}
.site-header-inner {
  max-width: 56rem; margin: 0 auto; padding: 0 1rem; height: 3.75rem;
  display: flex; align-items: center; gap: 1.25rem;
}

.brand {
  display: inline-flex; align-items: center; gap: 0.55rem;
  font-weight: 700; font-size: 1.05rem; letter-spacing: -0.01em; color: var(--fg); text-decoration: none;
}
.brand:hover { color: var(--fg); }
.brand-mark {
  display: inline-grid; place-items: center; width: 1.9rem; height: 1.9rem; border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 60%, #a855f7));
  color: #fff; font-size: 1.05rem; box-shadow: var(--shadow-sm);
}
.brand-mark-lg { width: 3rem; height: 3rem; border-radius: 12px; font-size: 1.5rem; margin-bottom: 1rem; }

.nav-tabs { display: flex; align-self: stretch; gap: 0.25rem; margin-right: auto; }
.nav-tab {
  position: relative; display: inline-flex; align-items: center; gap: 0.45rem;
  padding: 0 0.75rem; color: var(--muted); text-decoration: none; font-weight: 500; font-size: 0.92rem;
  border-radius: var(--radius-sm);
  transition: color 0.15s;
}
.nav-tab:hover { color: var(--fg); }
.nav-tab::after {
  content: ""; position: absolute; left: 0.6rem; right: 0.6rem; bottom: -1px; height: 2px;
  border-radius: 2px 2px 0 0; background: transparent; transition: background 0.15s;
}
.nav-tab[aria-current="page"] { color: var(--fg); }
.nav-tab[aria-current="page"]::after { background: var(--accent); }
.nav-tab svg { font-size: 1.05rem; }

/* Profile menu */
.profile { position: relative; }
.profile-button {
  display: inline-flex; align-items: center; gap: 0.3rem; padding: 0.2rem 0.4rem 0.2rem 0.2rem;
  background: transparent; border: 1px solid transparent; border-radius: 999px; color: var(--muted);
}
.profile-button:hover { background: var(--surface-2); border-color: var(--border); }
.profile-button[aria-expanded="true"] { background: var(--surface-2); border-color: var(--border); }
.profile-button .chevron { transition: transform 0.15s; }
.profile-button[aria-expanded="true"] .chevron { transform: rotate(180deg); }

.avatar {
  display: inline-grid; place-items: center; width: 2rem; height: 2rem; border-radius: 999px;
  background: linear-gradient(135deg, #f59f00, #e8590c); color: #fff;
  font-size: 0.78rem; font-weight: 700; letter-spacing: 0.02em;
}
.avatar-lg { width: 2.5rem; height: 2.5rem; font-size: 0.92rem; }

.profile-menu {
  position: absolute; right: 0; top: calc(100% + 0.5rem); z-index: 30; width: 16.5rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow-lg); padding: 0.35rem;
  animation: pop-in 0.12s ease-out;
  transform-origin: top right;
}
.profile-menu[hidden] { display: none; }
.profile-head { display: flex; gap: 0.7rem; align-items: center; padding: 0.6rem 0.6rem 0.75rem; border-bottom: 1px solid var(--border); margin-bottom: 0.35rem; }
.profile-id { display: grid; min-width: 0; line-height: 1.3; }
.profile-id strong { font-size: 0.9rem; font-weight: 600; }

.menu-list { list-style: none; margin: 0; padding: 0; }
.menu-footer { border-top: 1px solid var(--border); margin-top: 0.35rem; padding-top: 0.35rem; }
.menu-item {
  display: flex; width: 100%; align-items: center; gap: 0.6rem; padding: 0.5rem 0.6rem;
  border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--fg);
  font-size: 0.9rem; text-decoration: none; text-align: left; cursor: pointer;
}
.menu-item:hover, .menu-item:focus-visible { background: var(--surface-2); color: var(--fg); }
.menu-item svg { color: var(--muted); font-size: 1rem; }
.menu-item-danger, .menu-item-danger svg { color: var(--danger); }
.menu-item-danger:hover { background: var(--danger-soft); color: var(--danger); }

@keyframes pop-in {
  from { opacity: 0; transform: scale(0.96) translateY(-4px); }
  to { opacity: 1; transform: none; }
}

@media (max-width: 34rem) {
  .site-header-inner { gap: 0.5rem; }
  .brand { font-size: 0; gap: 0; }
  .nav-tab { padding: 0 0.55rem; }
}

/* ---------- Forms and buttons ---------- */

label { display: grid; gap: 0.3rem; font-size: 0.85rem; font-weight: 600; color: var(--fg); }
input, select, textarea, button { font: inherit; }
input, select, textarea {
  padding: 0.5rem 0.7rem; border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  background: var(--surface); color: var(--fg); min-width: 0; font-weight: 400; font-size: 0.92rem;
  transition: border-color 0.15s, box-shadow 0.15s;
}
input::placeholder, textarea::placeholder { color: color-mix(in srgb, var(--muted) 75%, transparent); }
input:hover, select:hover, textarea:hover { border-color: color-mix(in srgb, var(--accent) 40%, var(--border-strong)); }
input:focus-visible, select:focus-visible, textarea:focus-visible { border-color: var(--accent); }
textarea { resize: vertical; }

button {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.45rem;
  padding: 0.5rem 1rem; border-radius: var(--radius-sm); border: 1px solid var(--accent);
  background: var(--accent); color: var(--accent-fg); cursor: pointer; font-weight: 600; font-size: 0.9rem;
  box-shadow: var(--shadow-sm); transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
button:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
button:active { transform: translateY(1px); }
button:disabled { opacity: 0.6; cursor: progress; transform: none; }
button.secondary { background: var(--surface); color: var(--fg); border-color: var(--border-strong); }
button.secondary:hover { background: var(--surface-2); }
button.danger { background: var(--danger); border-color: var(--danger); color: var(--surface); }
button.danger:hover { background: color-mix(in srgb, var(--danger) 85%, #000); }
button.small { padding: 0.3rem 0.65rem; font-size: 0.82rem; }
button.link { background: none; border: none; color: var(--accent); padding: 0; text-decoration: underline; box-shadow: none; }

.icon-button {
  width: 2rem; height: 2rem; padding: 0; background: transparent; border: 1px solid transparent;
  color: var(--muted); box-shadow: none; font-size: 1rem;
}
.icon-button:hover { background: var(--surface-2); border-color: var(--border); color: var(--fg); }
.icon-button-danger:hover { background: var(--danger-soft); border-color: transparent; color: var(--danger); }

.error { color: var(--danger); margin: 0; font-size: 0.88rem; }
ul.error { padding-left: 1.2rem; }
.banner { padding: 0.65rem 0.9rem; border: 1px solid color-mix(in srgb, var(--danger) 35%, transparent); background: var(--danger-soft); border-radius: var(--radius-sm); }
.notice { margin: 0; padding: 0.65rem 0.9rem; border-radius: var(--radius-sm); background: var(--done-soft); color: var(--done); font-size: 0.9rem; }
.inline-error { display: flex; align-items: center; gap: 0.35rem; margin-top: 0.4rem; }

/* ---------- Cards and page structure ---------- */

.page-head { margin-bottom: 1.5rem; }
.page-head p { margin: 0; }
.lede { max-width: 44rem; margin: 0 0 1.25rem; }

.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 1.1rem 1.2rem; margin-bottom: 1.5rem; box-shadow: var(--shadow-sm);
}
details.card > summary {
  display: flex; align-items: center; gap: 0.55rem; cursor: pointer; font-weight: 600;
  list-style: none; border-radius: var(--radius-sm); margin: -0.25rem; padding: 0.25rem;
}
details.card > summary::-webkit-details-marker { display: none; }
details.card[open] > summary { margin-bottom: 0.9rem; }
.summary-icon {
  display: inline-grid; place-items: center; width: 1.6rem; height: 1.6rem; border-radius: 6px;
  background: var(--accent-soft); color: var(--accent); transition: transform 0.2s;
}
details[open] .summary-icon { transform: rotate(45deg); }

.task-form { display: grid; grid-template-columns: 2fr repeat(3, minmax(7rem, 1fr)); gap: 0.85rem; align-items: end; }
@media (max-width: 40rem) { .task-form { grid-template-columns: 1fr 1fr; } .task-form .grow { grid-column: 1 / -1; } }

/* ---------- Toolbar: status tabs and filters ---------- */

.toolbar { display: grid; gap: 0.85rem; margin-bottom: 1rem; }

.status-tabs {
  display: flex; gap: 0.25rem; padding: 0.25rem; overflow-x: auto; scrollbar-width: none;
  background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius); width: fit-content; max-width: 100%;
}
.status-tab {
  display: inline-flex; align-items: center; gap: 0.45rem; padding: 0.4rem 0.8rem; white-space: nowrap;
  border-radius: var(--radius-sm); color: var(--muted); font-weight: 500; font-size: 0.88rem; text-decoration: none;
  transition: background 0.15s, color 0.15s;
}
.status-tab:hover { color: var(--fg); }
.status-tab[aria-current="page"] { background: var(--surface); color: var(--fg); box-shadow: var(--shadow); }
.count {
  min-width: 1.4rem; padding: 0 0.4rem; border-radius: 999px; text-align: center;
  background: color-mix(in srgb, var(--muted) 15%, transparent); font-size: 0.75rem; font-weight: 600; line-height: 1.35rem;
}
.status-tab[aria-current="page"] .count { background: var(--accent-soft); color: var(--accent); }

.filters { display: flex; flex-wrap: wrap; gap: 0.6rem; align-items: center; }
.filters label { font-weight: 400; }
.search-field { position: relative; display: block; }
.search-field input { width: 100%; padding-left: 2.1rem; }
.search-icon { position: absolute; left: 0.7rem; top: 50%; transform: translateY(-50%); color: var(--muted); pointer-events: none; }
.clear-link { font-size: 0.88rem; }

/* ---------- Task list ---------- */

.list-count { margin: 0 0 0.6rem; }
.tasks { list-style: none; padding: 0; margin: 0; display: grid; gap: 0.6rem; }
.task {
  position: relative; display: flex; gap: 0.85rem; align-items: flex-start; padding: 0.9rem 0.9rem 0.9rem 1rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow-sm); transition: border-color 0.15s, box-shadow 0.15s;
  content-visibility: auto; contain-intrinsic-size: auto 5rem;
}
/* Priority accent stripe on the left edge. */
.task::before {
  content: ""; position: absolute; left: -1px; top: 0.75rem; bottom: 0.75rem; width: 3px; border-radius: 0 3px 3px 0;
  background: var(--stripe, transparent);
}
.task.priority-1 { --stripe: var(--danger); }
.task.priority-2 { --stripe: var(--warn); }
.task.priority-3 { --stripe: var(--progress); }
.task:hover { border-color: var(--border-strong); box-shadow: var(--shadow); }
.task[aria-busy="true"] { opacity: 0.65; }
.task.editing { display: block; padding: 1.1rem; border-color: var(--accent); box-shadow: var(--ring); }
.task.editing::before { display: none; }

/* Custom checkbox: the real input stays on top, invisible, so it keeps native behaviour. */
.check { position: relative; display: inline-grid; margin-top: 0.1rem; }
.check input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }
.check-box {
  display: grid; place-items: center; width: 1.3rem; height: 1.3rem; border-radius: 999px;
  border: 2px solid var(--border-strong); color: transparent; font-size: 0.8rem; transition: all 0.15s;
}
.check-box svg { stroke-width: 3.5; }
.check:hover .check-box { border-color: var(--done); color: color-mix(in srgb, var(--done) 50%, transparent); }
.check input:checked + .check-box { background: var(--done); border-color: var(--done); color: var(--surface); }
.check input:focus-visible + .check-box { box-shadow: var(--ring); }
.check input:disabled { cursor: progress; }

.task-body { flex: 1; min-width: 0; }
.task-title { font-weight: 600; overflow-wrap: anywhere; line-height: 1.4; }
.task.done .task-title { text-decoration: line-through; color: var(--muted); }
.task-notes { white-space: pre-wrap; color: var(--muted); overflow-wrap: anywhere; font-size: 0.9rem; margin-top: 0.15rem; }
.task-meta { display: flex; flex-wrap: wrap; gap: 0.4rem 0.6rem; align-items: center; margin-top: 0.5rem; font-size: 0.8rem; color: var(--muted); }

.due { display: inline-flex; align-items: center; gap: 0.35rem; }
.due-rel { font-weight: 600; }
.due-overdue { color: var(--danger); }
.due-soon { color: var(--warn); }

.pill {
  display: inline-flex; align-items: center; padding: 0.05rem 0.5rem; border-radius: 999px;
  font-weight: 600; font-size: 0.74rem; border: 1px solid transparent; background: var(--surface-2); color: var(--muted);
}
.priority-pill.p1 { background: var(--danger-soft); color: var(--danger); }
.priority-pill.p2 { background: var(--warn-soft); color: var(--warn); }
.priority-pill.p3 { background: var(--progress-soft); color: var(--progress); }
.status-pill { border-color: var(--border); background: transparent; }
.status-pill.status-in_progress { background: var(--progress-soft); color: var(--progress); border-color: transparent; }
.status-pill.status-done { background: var(--done-soft); color: var(--done); border-color: transparent; }

.task-actions { display: flex; gap: 0.15rem; align-items: center; opacity: 0.55; transition: opacity 0.15s; }
.task:hover .task-actions, .task:focus-within .task-actions { opacity: 1; }
@media (hover: none) { .task-actions { opacity: 1; } }
.confirm { display: flex; flex-wrap: wrap; gap: 0.4rem; align-items: center; justify-content: flex-end; font-size: 0.85rem; }
.task:has(.confirm) .task-actions { opacity: 1; }

/* ---------- Empty, error and loading states ---------- */

.empty {
  text-align: center; padding: 2.75rem 1rem; background: var(--surface);
  border: 1px dashed var(--border-strong); border-radius: var(--radius);
}
.empty p { margin: 0.25rem 0; }
.empty-icon {
  display: inline-grid; place-items: center; width: 3rem; height: 3rem; border-radius: 999px; margin-bottom: 0.6rem;
  background: var(--accent-soft); color: var(--accent); font-size: 1.4rem;
}
.empty-title { font-weight: 600; font-size: 1.02rem; }

.skeleton-list { display: grid; gap: 0.6rem; }
.skeleton-row, .skeleton-text {
  background: linear-gradient(90deg, var(--surface-2) 25%, var(--border) 50%, var(--surface-2) 75%);
  background-size: 200% 100%; animation: shimmer 1.3s ease-in-out infinite;
}
.skeleton-row { height: 4.6rem; border-radius: var(--radius); }
.skeleton-text { color: transparent; }
@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* ---------- Sign in ---------- */

.auth-card {
  max-width: 25rem; margin: 3rem auto 0; padding: 2rem 1.75rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: 14px; box-shadow: var(--shadow);
}
.auth-card > p { margin: 0 0 1.4rem; }
.auth-actions { display: grid; gap: 0.6rem; margin-top: 0.4rem; }
.auth-actions button { width: 100%; padding: 0.6rem 1rem; }

/* ---------- Import ---------- */

.dropzone {
  position: relative; display: flex; align-items: center; gap: 1rem; padding: 1.5rem;
  border: 2px dashed var(--border-strong); border-radius: var(--radius); background: var(--surface-2);
  cursor: pointer; font-weight: 400; transition: border-color 0.15s, background 0.15s;
}
.dropzone:hover, .dropzone:focus-within { border-color: var(--accent); background: var(--accent-soft); }
.dropzone:focus-within { box-shadow: var(--ring); }
.dropzone.has-file { border-style: solid; border-color: var(--accent); }
.dropzone input { position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; }
.dropzone-icon {
  display: inline-grid; place-items: center; width: 2.75rem; height: 2.75rem; border-radius: 10px;
  background: var(--surface); color: var(--accent); font-size: 1.3rem; box-shadow: var(--shadow-sm);
}
.dropzone-text { display: grid; gap: 0.1rem; min-width: 0; overflow-wrap: anywhere; }

.summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr)); gap: 0.75rem; list-style: none; padding: 0; margin: 0 0 1rem; }
.stat {
  display: grid; padding: 0.9rem 1rem; background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); color: var(--muted); font-size: 0.85rem; box-shadow: var(--shadow-sm);
}
.stat strong { font-size: 1.6rem; line-height: 1.2; color: var(--fg); }
.stat-ok strong { color: var(--done); }
.stat-bad strong { color: var(--danger); }

.section-head { justify-content: space-between; margin-top: 1.5rem; }
.table-wrap { overflow-x: auto; margin-top: 0.75rem; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); }
table { width: 100%; border-collapse: collapse; font-size: 0.88rem; }
th, td { text-align: left; vertical-align: top; padding: 0.6rem 0.8rem; border-bottom: 1px solid var(--border); }
th { background: var(--surface-2); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
tbody tr:last-child td { border-bottom: 0; }
td { overflow-wrap: anywhere; }
.reasons { margin: 0; padding-left: 1rem; }

toolUseResult.content:
:root {
  --bg: #f7f7fb;
  --surface: #ffffff;
  --surface-2: #f1f2f6;
  --fg: #16171d;
  --muted: #5e6170;
  --border: #e2e3ea;
  --border-strong: #c9cbd6;
  --accent: #3b5bdb;
  --accent-hover: #2f4ac0;
  --accent-soft: #e8edff;
  --accent-fg: #ffffff;
  --danger: #c92a2a;
  --danger-soft: #fdecec;
  --warn: #b35c00;
  --warn-soft: #fff3e0;
  --done: #2b8a3e;
  --done-soft: #e6f6ea;
  --progress: #1971c2;
  --progress-soft: #e7f1fc;
  --ring: 0 0 0 3px color-mix(in srgb, var(--accent) 35%, transparent);
  --shadow-sm: 0 1px 2px rgb(16 18 27 / 6%);
  --shadow: 0 1px 3px rgb(16 18 27 / 8%), 0 4px 12px rgb(16 18 27 / 5%);
  --shadow-lg: 0 10px 30px rgb(16 18 27 / 14%), 0 2px 6px rgb(16 18 27 / 6%);
  --radius: 10px;
  --radius-sm: 7px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1014;
    --surface: #17181e;
    --surface-2: #1f2028;
    --fg: #ececf1;
    --muted: #9c9fae;
    --border: #2b2d37;
    --border-strong: #3c3f4c;
    --accent: #7c95ff;
    --accent-hover: #98abff;
    --accent-soft: #1f2645;
    --accent-fg: #0b1020;
    --danger: #ff8787;
    --danger-soft: #3a1c1f;
    --warn: #ffb35c;
    --warn-soft: #3a2a14;
    --done: #69db7c;
    --done-soft: #16301d;
    --progress: #74c0fc;
    --progress-soft: #142a3d;
    --shadow-sm: 0 1px 2px rgb(0 0 0 / 40%);
    --shadow: 0 1px 3px rgb(0 0 0 / 40%), 0 4px 12px rgb(0 0 0 / 25%);
    --shadow-lg: 0 10px 30px rgb(0 0 0 / 55%), 0 2px 6px rgb(0 0 0 / 30%);
  }
}

/* ---------- Base ---------- */

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--fg);
  font: 15px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  -webkit-font-smoothing: antialiased;
}

main { max-width: 56rem; margin: 0 auto; padding: 2rem 1rem 5rem; }
h1 { font-size: 1.65rem; line-height: 1.2; letter-spacing: -0.02em; margin: 0 0 0.35rem; }
h2 { font-size: 1.2rem; letter-spacing: -0.01em; }
h3 { font-size: 1.02rem; margin: 0; }
a { color: var(--accent); text-underline-offset: 2px; }
a:hover { color: var(--accent-hover); }
code { background: var(--surface-2); border: 1px solid var(--border); padding: 0 0.3em; border-radius: 5px; font-size: 0.88em; }
svg { flex-shrink: 0; }

:focus-visible { outline: none; box-shadow: var(--ring); }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 1rem; top: -3rem; z-index: 100;
  background: var(--accent); color: var(--accent-fg); padding: 0.5rem 0.9rem; border-radius: var(--radius-sm);
  text-decoration: none; font-weight: 600;
}
.skip-link:focus { top: 0.75rem; color: var(--accent-fg); }

/* ---------- Utilities ---------- */

.row { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: center; }
.stack { display: grid; gap: 0.9rem; }
.muted { color: var(--muted); }
.small { font-size: 0.82rem; }
.grow { flex: 1 1 14rem; }
.full { grid-column: 1 / -1; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }

/* ---------- Header and navigation ---------- */

.site-header {
  position: sticky; top: 0; z-index: 20;
  background: color-mix(in srgb, var(--surface) 82%, transparent);
  backdrop-filter: saturate(180%) blur(12px);
  -webkit-backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--border);
}
.site-header-inner {
  max-width: 56rem; margin: 0 auto; padding: 0 1rem; height: 3.75rem;
  display: flex; align-items: center; gap: 1.25rem;
}

.brand {
  display: inline-flex; align-items: center; gap: 0.55rem;
  font-weight: 700; font-size: 1.05rem; letter-spacing: -0.01em; color: var(--fg); text-decoration: none;
}
.brand:hover { color: var(--fg); }
.brand-mark {
  display: inline-grid; place-items: center; width: 1.9rem; height: 1.9rem; border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 60%, #a855f7));
  color: #fff; font-size: 1.05rem; box-shadow: var(--shadow-sm);
}
.brand-mark-lg { width: 3rem; height: 3rem; border-radius: 12px; font-size: 1.5rem; margin-bottom: 1rem; }

.nav-tabs { display: flex; align-self: stretch; gap: 0.25rem; margin-right: auto; }
.nav-tab {
  position: relative; display: inline-flex; align-items: center; gap: 0.45rem;
  padding: 0 0.75rem; color: var(--muted); text-decoration: none; font-weight: 500; font-size: 0.92rem;
  border-radius: var(--radius-sm);
  transition: color 0.15s;
}
.nav-tab:hover { color: var(--fg); }
.nav-tab::after {
  content: ""; position: absolute; left: 0.6rem; right: 0.6rem; bottom: -1px; height: 2px;
  border-radius: 2px 2px 0 0; background: transparent; transition: background 0.15s;
}
.nav-tab[aria-current="page"] { color: var(--fg); }
.nav-tab[aria-current="page"]::after { background: var(--accent); }
.nav-tab svg { font-size: 1.05rem; }

/* Profile menu */
.profile { position: relative; }
.profile-button {
  display: inline-flex; align-items: center; gap: 0.3rem; padding: 0.2rem 0.4rem 0.2rem 0.2rem;
  background: transparent; border: 1px solid transparent; border-radius: 999px; color: var(--muted);
}
.profile-button:hover { background: var(--surface-2); border-color: var(--border); }
.profile-button[aria-expanded="true"] { background: var(--surface-2); border-color: var(--border); }
.profile-button .chevron { transition: transform 0.15s; }
.profile-button[aria-expanded="true"] .chevron { transform: rotate(180deg); }

.avatar {
  display: inline-grid; place-items: center; width: 2rem; height: 2rem; border-radius: 999px;
  background: linear-gradient(135deg, #f59f00, #e8590c); color: #fff;
  font-size: 0.78rem; font-weight: 700; letter-spacing: 0.02em;
}
.avatar-lg { width: 2.5rem; height: 2.5rem; font-size: 0.92rem; }

.profile-menu {
  position: absolute; right: 0; top: calc(100% + 0.5rem); z-index: 30; width: 16.5rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow-lg); padding: 0.35rem;
  animation: pop-in 0.12s ease-out;
  transform-origin: top right;
}
.profile-menu[hidden] { display: none; }
.profile-head { display: flex; gap: 0.7rem; align-items: center; padding: 0.6rem 0.6rem 0.75rem; border-bottom: 1px solid var(--border); margin-bottom: 0.35rem; }
.profile-id { display: grid; min-width: 0; line-height: 1.3; }
.profile-id strong { font-size: 0.9rem; font-weight: 600; }

.menu-list { list-style: none; margin: 0; padding: 0; }
.menu-footer { border-top: 1px solid var(--border); margin-top: 0.35rem; padding-top: 0.35rem; }
.menu-item {
  display: flex; width: 100%; align-items: center; gap: 0.6rem; padding: 0.5rem 0.6rem;
  border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--fg);
  font-size: 0.9rem; text-decoration: none; text-align: left; cursor: pointer;
}
.menu-item:hover, .menu-item:focus-visible { background: var(--surface-2); color: var(--fg); }
.menu-item svg { color: var(--muted); font-size: 1rem; }
.menu-item-danger, .menu-item-danger svg { color: var(--danger); }
.menu-item-danger:hover { background: var(--danger-soft); color: var(--danger); }

@keyframes pop-in {
  from { opacity: 0; transform: scale(0.96) translateY(-4px); }
  to { opacity: 1; transform: none; }
}

@media (max-width: 34rem) {
  .site-header-inner { gap: 0.5rem; }
  .brand { font-size: 0; gap: 0; }
  .nav-tab { padding: 0 0.55rem; }
}

/* ---------- Forms and buttons ---------- */

label { display: grid; gap: 0.3rem; font-size: 0.85rem; font-weight: 600; color: var(--fg); }
input, select, textarea, button { font: inherit; }
input, select, textarea {
  padding: 0.5rem 0.7rem; border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  background: var(--surface); color: var(--fg); min-width: 0; font-weight: 400; font-size: 0.92rem;
  transition: border-color 0.15s, box-shadow 0.15s;
}
input::placeholder, textarea::placeholder { color: color-mix(in srgb, var(--muted) 75%, transparent); }
input:hover, select:hover, textarea:hover { border-color: color-mix(in srgb, var(--accent) 40%, var(--border-strong)); }
input:focus-visible, select:focus-visible, textarea:focus-visible { border-color: var(--accent); }
textarea { resize: vertical; }

button {
  display: inline-flex; align-items: center; justify-content: center; gap: 0.45rem;
  padding: 0.5rem 1rem; border-radius: var(--radius-sm); border: 1px solid var(--accent);
  background: var(--accent); color: var(--accent-fg); cursor: pointer; font-weight: 600; font-size: 0.9rem;
  box-shadow: var(--shadow-sm); transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
button:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
button:active { transform: translateY(1px); }
button:disabled { opacity: 0.6; cursor: progress; transform: none; }
button.secondary { background: var(--surface); color: var(--fg); border-color: var(--border-strong); }
button.secondary:hover { background: var(--surface-2); }
button.danger { background: var(--danger); border-color: var(--danger); color: var(--surface); }
button.danger:hover { background: color-mix(in srgb, var(--danger) 85%, #000); }
button.small { padding: 0.3rem 0.65rem; font-size: 0.82rem; }
button.link { background: none; border: none; color: var(--accent); padding: 0; text-decoration: underline; box-shadow: none; }

.icon-button {
  width: 2rem; height: 2rem; padding: 0; background: transparent; border: 1px solid transparent;
  color: var(--muted); box-shadow: none; font-size: 1rem;
}
.icon-button:hover { background: var(--surface-2); border-color: var(--border); color: var(--fg); }
.icon-button-danger:hover { background: var(--danger-soft); border-color: transparent; color: var(--danger); }

.error { color: var(--danger); margin: 0; font-size: 0.88rem; }
ul.error { padding-left: 1.2rem; }
.banner { padding: 0.65rem 0.9rem; border: 1px solid color-mix(in srgb, var(--danger) 35%, transparent); background: var(--danger-soft); border-radius: var(--radius-sm); }
.notice { margin: 0; padding: 0.65rem 0.9rem; border-radius: var(--radius-sm); background: var(--done-soft); color: var(--done); font-size: 0.9rem; }
.inline-error { display: flex; align-items: center; gap: 0.35rem; margin-top: 0.4rem; }

/* ---------- Cards and page structure ---------- */

.page-head { margin-bottom: 1.5rem; }
.page-head p { margin: 0; }
.lede { max-width: 44rem; margin: 0 0 1.25rem; }

.card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 1.1rem 1.2rem; margin-bottom: 1.5rem; box-shadow: var(--shadow-sm);
}
details.card > summary {
  display: flex; align-items: center; gap: 0.55rem; cursor: pointer; font-weight: 600;
  list-style: none; border-radius: var(--radius-sm); margin: -0.25rem; padding: 0.25rem;
}
details.card > summary::-webkit-details-marker { display: none; }
details.card[open] > summary { margin-bottom: 0.9rem; }
.summary-icon {
  display: inline-grid; place-items: center; width: 1.6rem; height: 1.6rem; border-radius: 6px;
  background: var(--accent-soft); color: var(--accent); transition: transform 0.2s;
}
details[open] .summary-icon { transform: rotate(45deg); }

.task-form { display: grid; grid-template-columns: 2fr repeat(3, minmax(7rem, 1fr)); gap: 0.85rem; align-items: end; }
@media (max-width: 40rem) { .task-form { grid-template-columns: 1fr 1fr; } .task-form .grow { grid-column: 1 / -1; } }

/* ---------- Toolbar: status tabs and filters ---------- */

.toolbar { display: grid; gap: 0.85rem; margin-bottom: 1rem; }

.status-tabs {
  display: flex; gap: 0.25rem; padding: 0.25rem; overflow-x: auto; scrollbar-width: none;
  background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius); width: fit-content; max-width: 100%;
}
.status-tab {
  display: inline-flex; align-items: center; gap: 0.45rem; padding: 0.4rem 0.8rem; white-space: nowrap;
  border-radius: var(--radius-sm); color: var(--muted); font-weight: 500; font-size: 0.88rem; text-decoration: none;
  transition: background 0.15s, color 0.15s;
}
.status-tab:hover { color: var(--fg); }
.status-tab[aria-current="page"] { background: var(--surface); color: var(--fg); box-shadow: var(--shadow); }
.count {
  min-width: 1.4rem; padding: 0 0.4rem; border-radius: 999px; text-align: center;
  background: color-mix(in srgb, var(--muted) 15%, transparent); font-size: 0.75rem; font-weight: 600; line-height: 1.35rem;
}
.status-tab[aria-current="page"] .count { background: var(--accent-soft); color: var(--accent); }

.filters { display: flex; flex-wrap: wrap; gap: 0.6rem; align-items: center; }
.filters label { font-weight: 400; }
.search-field { position: relative; display: block; }
.search-field input { width: 100%; padding-left: 2.1rem; }
.search-icon { position: absolute; left: 0.7rem; top: 50%; transform: translateY(-50%); color: var(--muted); pointer-events: none; }
.clear-link { font-size: 0.88rem; }

/* ---------- Task list ---------- */

.list-count { margin: 0 0 0.6rem; }
.tasks { list-style: none; padding: 0; margin: 0; display: grid; gap: 0.6rem; }
.task {
  position: relative; display: flex; gap: 0.85rem; align-items: flex-start; padding: 0.9rem 0.9rem 0.9rem 1rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow-sm); transition: border-color 0.15s, box-shadow 0.15s;
  content-visibility: auto; contain-intrinsic-size: auto 5rem;
}
/* Priority accent stripe on the left edge. */
.task::before {
  content: ""; position: absolute; left: -1px; top: 0.75rem; bottom: 0.75rem; width: 3px; border-radius: 0 3px 3px 0;
  background: var(--stripe, transparent);
}
.task.priority-1 { --stripe: var(--danger); }
.task.priority-2 { --stripe: var(--warn); }
.task.priority-3 { --stripe: var(--progress); }
.task:hover { border-color: var(--border-strong); box-shadow: var(--shadow); }
.task[aria-busy="true"] { opacity: 0.65; }
.task.editing { display: block; padding: 1.1rem; border-color: var(--accent); box-shadow: var(--ring); }
.task.editing::before { display: none; }

/* Custom checkbox: the real input stays on top, invisible, so it keeps native behaviour. */
.check { position: relative; display: inline-grid; margin-top: 0.1rem; }
.check input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }
.check-box {
  display: grid; place-items: center; width: 1.3rem; height: 1.3rem; border-radius: 999px;
  border: 2px solid var(--border-strong); color: transparent; font-size: 0.8rem; transition: all 0.15s;
}
.check-box svg { stroke-width: 3.5; }
