.due { display: inline-flex; align-items: center; gap: 0.35rem; }
.due-rel { font-weight: 600; }
.due-overdue { color: var(--danger); }
.due-soon { color: var(--warn); }

.pill {
  display: inline-flex; align-items: center; padding: 0.05rem 0.5rem; border-radius: 999px;
  font-weight: 600; font-size: 0.74rem; border: 1px solid transparent; background: var(--surface-2); color: var(--muted);
}
.priority-pill.p1 { background: var(--danger-soft); color: var(--danger); }
.priority-pill.p2 { background: var(--warn-soft); color: var(--warn); }
.priority-pill.p3 { background: var(--progress-soft); color: var(--progress); }
.status-pill { border-color: var(--border); background: transparent; }
.status-pill.status-in_progress { background: var(--progress-soft); color: var(--progress); border-color: transparent; }
.status-pill.status-done { background: var(--done-soft); color: var(--done); border-color: transparent; }

.task-actions { display: flex; gap: 0.15rem; align-items: center; opacity: 0.55; transition: opacity 0.15s; }
.task:hover .task-actions, .task:focus-within .task-actions { opacity: 1; }
@media (hover: none) { .task-actions { opacity: 1; } }
.confirm { display: flex; flex-wrap: wrap; gap: 0.4rem; align-items: center; justify-content: flex-end; font-size: 0.85rem; }
.task:has(.confirm) .task-actions { opacity: 1; }

/* ---------- Empty, error and loading states ---------- */

.empty {
  text-align: center; padding: 2.75rem 1rem; background: var(--surface);
  border: 1px dashed var(--border-strong); border-radius: var(--radius);
}
.empty p { margin: 0.25rem 0; }
.empty-icon {
  display: inline-grid; place-items: center; width: 3rem; height: 3rem; border-radius: 999px; margin-bottom: 0.6rem;
  background: var(--accent-soft); color: var(--accent); font-size: 1.4rem;
}
.empty-title { font-weight: 600; font-size: 1.02rem; }

.skeleton-list { display: grid; gap: 0.6rem; }
.skeleton-row, .skeleton-text {
  background: linear-gradient(90deg, var(--surface-2) 25%, var(--border) 50%, var(--surface-2) 75%);
  background-size: 200% 100%; animation: shimmer 1.3s ease-in-out infinite;
